/*
====CHAINCODE EXECUTION SAMPLES (CLI) ==================

==== Invoke assets ====
peer chaincode invoke -C myc1 -n asset_transfer -c '{"Args":["CreateAsset","asset1","blue","5","tom","35"]}'
peer chaincode invoke -C myc1 -n asset_transfer -c '{"Args":["CreateAsset","asset2","red","4","tom","50"]}'
peer chaincode invoke -C myc1 -n asset_transfer -c '{"Args":["CreateAsset","asset3","blue","6","tom","70"]}'
peer chaincode invoke -C myc1 -n asset_transfer -c '{"Args":["TransferAsset","asset2","jerry"]}'
peer chaincode invoke -C myc1 -n asset_transfer -c '{"Args":["TransferAssetByColor","blue","jerry"]}'
peer chaincode invoke -C myc1 -n asset_transfer -c '{"Args":["DeleteAsset","asset1"]}'

==== Query assets ====
peer chaincode query -C myc1 -n asset_transfer -c '{"Args":["ReadAsset","asset1"]}'
peer chaincode query -C myc1 -n asset_transfer -c '{"Args":["GetAssetsByRange","asset1","asset3"]}'
peer chaincode query -C myc1 -n asset_transfer -c '{"Args":["GetAssetHistory","asset1"]}'

Rich Query (Only supported if CouchDB is used as state database):
peer chaincode query -C myc1 -n asset_transfer -c '{"Args":["QueryAssetsByOwner","tom"]}'
peer chaincode query -C myc1 -n asset_transfer -c '{"Args":["QueryAssets","{\"selector\":{\"owner\":\"tom\"}}"]}'

Rich Query with Pagination (Only supported if CouchDB is used as state database):
peer chaincode query -C myc1 -n asset_transfer -c '{"Args":["QueryAssetsWithPagination","{\"selector\":{\"owner\":\"tom\"}}","3",""]}'

INDEXES TO SUPPORT COUCHDB RICH QUERIES

Indexes in CouchDB are required in order to make JSON queries efficient and are required for
any JSON query with a sort. Indexes may be packaged alongside
chaincode in a META-INF/statedb/couchdb/indexes directory. Each index must be defined in its own
text file with extension *.json with the index definition formatted in JSON following the
CouchDB index JSON syntax as documented at:
http://docs.couchdb.org/en/2.3.1/api/database/find.html#db-index

This asset transfer ledger example chaincode demonstrates a packaged
index which you can find in META-INF/statedb/couchdb/indexes/indexOwner.json.

If you have access to the your peer's CouchDB state database in a development environment,
you may want to iteratively test various indexes in support of your chaincode queries.  You
can use the CouchDB Fauxton interface or a command line curl utility to create and update
indexes. Then once you finalize an index, include the index definition alongside your
chaincode in the META-INF/statedb/couchdb/indexes directory, for packaging and deployment
to managed environments.

In the examples below you can find index definitions that support asset transfer ledger
chaincode queries, along with the syntax that you can use in development environments
to create the indexes in the CouchDB Fauxton interface or a curl command line utility.


Index for docType, owner.

Example curl command line to define index in the CouchDB channel_chaincode database
curl -i -X POST -H "Content-Type: application/json" -d "{\"index\":{\"fields\":[\"docType\",\"owner\"]},\"name\":\"indexOwner\",\"ddoc\":\"indexOwnerDoc\",\"type\":\"json\"}" http://hostname:port/myc1_assets/_index


Index for docType, owner, size (descending order).

Example curl command line to define index in the CouchDB channel_chaincode database:
curl -i -X POST -H "Content-Type: application/json" -d "{\"index\":{\"fields\":[{\"size\":\"desc\"},{\"docType\":\"desc\"},{\"owner\":\"desc\"}]},\"ddoc\":\"indexSizeSortDoc\", \"name\":\"indexSizeSortDesc\",\"type\":\"json\"}" http://hostname:port/myc1_assets/_index

Rich Query with index design doc and index name specified (Only supported if CouchDB is used as state database):
peer chaincode query -C myc1 -n asset_transfer -c '{"Args":["QueryAssets","{\"selector\":{\"docType\":\"asset\",\"owner\":\"tom\"}, \"use_index\":[\"_design/indexOwnerDoc\", \"indexOwner\"]}"]}'

Rich Query with index design doc specified only (Only supported if CouchDB is used as state database):
peer chaincode query -C myc1 -n asset_transfer -c '{"Args":["QueryAssets","{\"selector\":{\"docType\":{\"$eq\":\"asset\"},\"owner\":{\"$eq\":\"tom\"},\"size\":{\"$gt\":0}},\"fields\":[\"docType\",\"owner\",\"size\"],\"sort\":[{\"size\":\"desc\"}],\"use_index\":\"_design/indexSizeSortDoc\"}"]}'
*/

package main

import (
	"encoding/json"
	"fmt"
	"log"
	"time"

	"github.com/hyperledger/fabric-chaincode-go/v2/shim"
	"github.com/hyperledger/fabric-contract-api-go/v2/contractapi"
)

const index = "inven"

// SimpleChaincode implements the fabric-contract-api-go programming model
type SimpleChaincode struct {
	contractapi.Contract
}

type Asset struct {
	DocType           string `json:"docType"` //docType is used to distinguish the various types of objects in state database
	ID                string `json:"ID"`      //the field tags are needed to keep case from bouncing around
	NameProduct       string `json:"nameproduct"`
	Quantity          int    `json:"quantitiy"`
	Warehouse         string `json:"warehouse"`
	ResponsiblePerson string `json:"responsibleperson"`
	Status            string `json:"status"`
	Timestamp         string `json:"timestamp"`
}

// HistoryQueryResult structure used for returning result of history query
type HistoryQueryResult struct {
	Record    *Asset    `json:"record"`
	TxId      string    `json:"txId"`
	Timestamp time.Time `json:"timestamp"`
	IsDelete  bool      `json:"isDelete"`
}

// PaginatedQueryResult structure used for returning paginated query results and metadata
type PaginatedQueryResult struct {
	Records             []*Asset `json:"records"`
	FetchedRecordsCount int32    `json:"fetchedRecordsCount"`
	Bookmark            string   `json:"bookmark"`
}

// CreateAsset initializes a new asset in the ledger
func (t *SimpleChaincode) CreateAsset(ctx contractapi.TransactionContextInterface, assetID, nameproduct string, quantity int, warehouse string, responsibleperson string, status string, timestamp string) error {
	// 🔹 Cek apakah asset sudah ada
	exists, err := t.AssetExists(ctx, assetID)
	if err != nil {
		return fmt.Errorf("failed to check asset existence: %v", err)
	}
	if exists {
		return fmt.Errorf("asset already exists: %s", assetID)
	}

	// 🔹 Buat objek aset
	asset := &Asset{
		DocType:           "inventory",
		ID:                assetID,
		NameProduct:       nameproduct,
		Quantity:          quantity,
		Warehouse:         warehouse,
		ResponsiblePerson: responsibleperson,
		Status:            status,
		Timestamp:         timestamp,
	}

	// 🔹 Marshal ke JSON
	assetBytes, err := json.Marshal(asset)
	if err != nil {
		return fmt.Errorf("failed to marshal asset: %v", err)
	}

	// 🔹 Simpan data utama aset dengan key = assetID
	err = ctx.GetStub().PutState(asset.ID, assetBytes)
	if err != nil {
		return fmt.Errorf("failed to save asset: %v", err)
	}

	// 🔹 Buat composite key untuk warehouse~status~id
	warehouseStatusKey, err := ctx.GetStub().CreateCompositeKey("warehouse~status~id", []string{warehouse, status, assetID})
	if err != nil {
		return fmt.Errorf("failed to create warehouseStatusKey: %v", err)
	}
	err = ctx.GetStub().PutState(warehouseStatusKey, []byte{0x00})
	if err != nil {
		return fmt.Errorf("failed to save warehouseStatusKey: %v", err)
	}

	// 🔹 Buat composite key untuk warehouse~timestamp~id
	warehouseTimestampKey, err := ctx.GetStub().CreateCompositeKey("warehouse~timestamp~id", []string{warehouse, timestamp, assetID})
	if err != nil {
		return fmt.Errorf("failed to create warehouseTimestampKey: %v", err)
	}
	err = ctx.GetStub().PutState(warehouseTimestampKey, []byte{0x00})
	if err != nil {
		return fmt.Errorf("failed to save warehouseTimestampKey: %v", err)
	}

	return nil
}

func (s *SimpleChaincode) QueryByWarehouseAndStatus(ctx contractapi.TransactionContextInterface, warehouse string, status string) ([]*Asset, error) {
	resultsIterator, err := ctx.GetStub().GetStateByPartialCompositeKey("inventory", []string{warehouse, status})
	if err != nil {
		return nil, err
	}
	defer resultsIterator.Close()

	var assets []*Asset
	for resultsIterator.HasNext() {
		queryResponse, err := resultsIterator.Next()
		if err != nil {
			return nil, err
		}

		var asset Asset
		_ = json.Unmarshal(queryResponse.Value, &asset)
		assets = append(assets, &asset)
	}

	return assets, nil
}

func (t *SimpleChaincode) QueryCompositeWarehouseStatusCombination(ctx contractapi.TransactionContextInterface, warehouse string, status string) ([]Asset, error) {
	// Gunakan composite key prefix untuk scanning
	resultsIterator, err := ctx.GetStub().GetStateByPartialCompositeKey("warehouse~status~id", []string{warehouse, status})
	if err != nil {
		return nil, fmt.Errorf("failed to get composite keys: %v", err)
	}
	defer resultsIterator.Close()

	var assets []Asset
	for resultsIterator.HasNext() {
		response, err := resultsIterator.Next()
		if err != nil {
			return nil, err
		}

		// Ambil elemen dari composite key → ambil ID
		_, compositeKeyParts, err := ctx.GetStub().SplitCompositeKey(response.Key)
		if err != nil {
			return nil, err
		}
		assetID := compositeKeyParts[2] // index ke-2 adalah ID (warehouse~status~id)

		// Ambil dokumen lengkap dari CouchDB by ID
		assetBytes, err := ctx.GetStub().GetState(assetID)
		if err != nil {
			return nil, err
		}

		if assetBytes == nil {
			continue
		}

		var asset Asset
		err = json.Unmarshal(assetBytes, &asset)
		if err != nil {
			return nil, err
		}

		assets = append(assets, asset)
	}

	return assets, nil
}

func determineIndexName(field string) string {
	switch field {
	case "ID":
		return "inventoryIndexDoc"
	case "warehouse":
		return "warehouseIndexDoc"
	case "status":
		return "statusIndexDoc"
	case "responsibleperson":
		return "responsiblepersonIndexDoc"
	case "timestamp":
		return "timestampIndexDoc"
	default:
		return "inventoryIndexDoc"
	}
}

func (t *SimpleChaincode) runMangoQuery(ctx contractapi.TransactionContextInterface, field string, value string) ([]Asset, error) {
	indexName := determineIndexName(field)

	var selector string
	if field == "ID" {
		selector = fmt.Sprintf(`{
			"selector": {
				"docType": "inventory",
				"ID": { "$regex": "^%s" }
			},
			"use_index": ["%s"]
		}`, value, indexName)
	} else {
		selector = fmt.Sprintf(`{
			"selector": {
				"docType": "inventory",
				"%s": "%s"
			},
			"use_index": ["%s"]
		}`, field, value, indexName)
	}

	resultsIterator, err := ctx.GetStub().GetQueryResult(selector)
	if err != nil {
		return nil, err
	}
	defer resultsIterator.Close()

	var assets []Asset
	for resultsIterator.HasNext() {
		queryResponse, err := resultsIterator.Next()
		if err != nil {
			return nil, err
		}

		var asset Asset
		err = json.Unmarshal(queryResponse.Value, &asset)
		if err != nil {
			return nil, err
		}
		assets = append(assets, asset)
	}
	return assets, nil
}

func (t *SimpleChaincode) queryByCompositeKey(ctx contractapi.TransactionContextInterface, warehouse string, status string) ([]Asset, error) {
	iterator, err := ctx.GetStub().GetStateByPartialCompositeKey("warehouse~status~id", []string{warehouse, status})
	if err != nil {
		return nil, err
	}
	defer iterator.Close()

	var assets []Asset
	for iterator.HasNext() {
		kvResult, err := iterator.Next()
		if err != nil {
			return nil, err
		}
		_, keyParts, err := ctx.GetStub().SplitCompositeKey(kvResult.Key)
		if err != nil {
			return nil, err
		}
		assetID := keyParts[2] // urutan: warehouse, status, id

		assetBytes, err := ctx.GetStub().GetState(assetID)
		if err != nil {
			return nil, err
		}
		var asset Asset
		err = json.Unmarshal(assetBytes, &asset)
		if err != nil {
			return nil, err
		}
		assets = append(assets, asset)
	}
	return assets, nil
}

